input.sparql:
SELECT DISTINCT ?entity ?entityName ?point ?pointName ?tsid WHERE {
  ?point a brick:ElectricPower ; brick:isPointOf ?entity .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?entity rdfs:label ?entityName . }
}

SELECT DISTINCT ?point ?tsid ?pointClass WHERE {
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point a ?pointClass . }
} LIMIT 50

SELECT DISTINCT ?point ?label WHERE {
  ?point a brick:ElectricPower .
} LIMIT 20

SELECT DISTINCT ?cls WHERE {
  ?p a ?cls .
  FILTER (str(?cls) CONTAINS "Power" || str(?cls) CONTAINS "Electric" || str(?cls) CONTAINS "Energy")
}

SELECT ?point ?entity ?label ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point brick:isPointOf ?entity .
  OPTIONAL { ?entity rdfs:label ?label . }
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid . }
}
